'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes={
 theme:{name:'thematic portfolio',subject:'AI infrastructure',title:'AI infrastructure theme portfolio',thesis:'bullish on AI infrastructure demand over the long term, expressed through related assets while limiting single-company risk.',horizon:'1–3  years',holding:'Not provided',intro:'bullish on AI infrastructure, but want more than one company. Can you build a portfolio around this thesis?',reply:'We can turn your thesis into a thematic portfolio, then discuss concentration and risk limits.\n\nThe right side shows a theme core, diversified holdings, and cash buffer. See the full report for securities, weights, and rationale.\n\nIf markets move against your view, we can explore portfolio protection.',structure:'Turn a thesis into a portfolio',thesisLabel:'Your investment thesis',blocks:['Theme core','Diversified allocation','Cash buffer'],weights:[60,25,15],roleNotes:['Express the main investment thesis','Reduce single-security concentration','Preserve flexibility'],watch:['Companies in the same theme can share risks; multiple stocks may still be highly concentrated.','Next, confirm accessible markets, current holdings, and acceptable losses.'],rows:[['Compute-related securities A (placeholder)','30%','Theme core','Express a compute-infrastructure research thesis'],['Network-related securities B (placeholder)','20%','Theme core','Covers different industry segments; correlations need verification'],['Power-related securities C (placeholder)','10%','Theme core','Explore supporting infrastructure, subject to independent research'],['Non-theme asset basket (to be selected)','25%','Diversified allocation','Reduce theme concentration; verify correlations with data'],['Cash and equivalents (to be selected)','15%','Liquidity','Preserve capital without direct theme-equity exposure']],questions:['Does the core demand thesis hold?','What would invalidate the investment thesis?','Does the current portfolio already have similar exposure?'],next:'Generate hedge plan'},
 stock:{name:'Security research',subject:'NVDA / NVIDIA',title:'NVDA Security research',thesis:'want to research NVDA Check valuation, business assumptions, and position limits before making a conditional recommendation.',horizon:'6–12  months',holding:'Not provided',intro:'What do you think of NVIDIA? Would it fit my portfolio?',reply:'Start with security research before reaching a purchase conclusion.\n\nThe right side lists questions to verify and a path toward a decision. Add holdings, horizon, and risk preferences to continue.\n\nNo financial reports or quotes are connected; the report provides a research framework and conclusions remain unverified.',structure:'From research questions to investment decisions',thesisLabel:'Question to evaluate',watch:['Verify the security thesis against current financials, prices, and valuation; no live conclusion is provided here.','Discuss the research conclusion, position size, and portfolio inclusion separately.'],rows:[['Business and demand','To be verified','Research questions','Check revenue sources, demand durability, and competition'],['Valuation and expectations','To be verified','Research questions','Test assumptions with dated prices and financial data'],['Portfolio fit','Incomplete','Holdings constraints','Confirm existing technology and semiconductor exposure'],['Recommendation','No conclusion yet for ','Research status','Make conditional recommendations after verifying evidence, prices, and personal constraints']],questions:['Is business growth already priced in?','What is the strongest evidence against the thesis?','Would adding it increase existing concentration?'],next:'build a portfolio around it'},
 hedge:{name:'Risk hedge',subject:'AI theme holdings',title:'AI Theme holdings hedge',thesis:'Retain part of the long-term thesis while protecting against temporary declines; distinguish exposure reduction, diversification, and contract hedging.',horizon:'3–6  months',holding:'AI Thematic portfolio (example)',intro:'I want to retain  AI  theme holdings, but worry about a short-term pullback. Can you design a hedge?',reply:'First, confirm which holdings to protect, the horizon, and your cost budget.\n\nThe right side separates holdings from protection candidates. Reducing or diversifying exposure does not fix the loss amount; verify contract horizons, costs, and suitability.\n\nSee the report for details. This is a draft structure without uncalculated hedge ratios.',structure:'Identify exposure before designing protection',thesisLabel:'Risk you want to address',watch:['Hedge ratios, costs, and loss limits are not calculated; protection effectiveness is unverified.','Diversified assets may fall together; protective options involve premiums, expiry, and execution conditions.'],rows:[['Reduce existing exposure','Pending','Adjust holdings','Confirm directional exposure to retain; upside participation decreases'],['Cash buffer / Diversified assets','Pending','Risk management','Diversifies risk without guaranteeing offsets to existing losses'],['Protective put (candidate)','Pending','Contract hedge','Verify underlying, multiplier, expiry, strike, and premium'],['Protection horizon and cost budget','Incomplete','Plan constraints','Determined by position size, intended protection, and affordable cost']],questions:['Which actual holdings and market value need protection?','What horizon and risks should protection cover?','Acceptable protection cost and trading constraints?'],next:'Add protection conditions'},
 allocation:{name:'asset allocation',subject:'Long-term multi-asset portfolio',title:'Long-term multi-asset portfolio',thesis:'Create an initial mix of equities, bonds, and liquid assets for long-term goals, checking total risk against existing holdings.',horizon:'3  years or more',holding:'Not provided',intro:'Help me plan the overall allocation for a long-term portfolio.',reply:'Start allocation planning with funding needs, horizon, and tolerable volatility.\n\nThe right side shows a multi-asset example; weights and rationale are in the report. Add your budget, horizon, and holdings in the research background.',structure:'Organize assets around long-term goals',thesisLabel:'Your financial goals',blocks:['Growth assets','Defensive assets','Liquidity'],weights:[55,35,10],roleNotes:['Long-term growth exposure','Diversify some equity risk','Meets funding needs'],watch:['Asset correlations change with market conditions; diversification cannot eliminate losses.','Taxes, product fees, actual holdings, and withdrawals are not included.'],rows:[['Equities (to be selected)','55%','Growth assets','Participate in equity markets with the associated volatility'],['Bonds (to be selected)','25%','Defensive assets','Adds a different risk source, with interest-rate and credit risk'],['Gold (to be selected)','10%','Defensive assets','Add other risk sources; verify correlations'],['Cash and equivalents (to be selected)','10%','Liquidity','Provides liquidity and flexibility']],questions:['When will you need the funds?','Which assets do you already hold?','How much loss can you tolerate?'],next:'lower risk'}
};
modes.options={name:'Options portfolio',subject:'call spread',title:'Call-spread portfolio',thesis:'Express a moderately bullish thesis with a call spread; underlying, strikes, expiry, and cost remain to be selected.',horizon:'3–6  months',holding:'Not provided',rows:[['Buy call','Pending','Strategy legs','Lower strike; verify underlying, contract, and premium'],['Sell call','Pending','Strategy legs','Same underlying, expiry, and quantity, higher strike; verify multiplier'],['Net cost and risk limits','To be calculated','Strategy constraints','Depends on actual quotes, contract counts, fees, and exercise arrangements'],['Expiry and execution conditions','Incomplete','Execution constraints','Consider early exercise, assignment, liquidity, and account permissions']],questions:['Which underlying and expiry should we research?','Actual quotes, contract multipliers, and quantities?','Cost budget and tolerable loss range?'],watch:['Illustrative standard expiry payoff, not an actual quote or return forecast.','Assess actual risk alongside early exercise, assignment, fees, and execution.']};
const fresh=mode=>({subject:modes[mode].subject,thesis:modes[mode].thesis,amount:500000,horizon:modes[mode].horizon,risk:'balanced',holding:modes[mode].holding,version:1});
let state={mode:'theme',contexts:Object.fromEntries(Object.keys(modes).map(k=>[k,fresh(k)])),messages:[],hasPortfolio:false};
try{const saved=JSON.parse(localStorage.getItem('folio-simple-v3')||'null');if(saved&&modes[saved.mode]&&saved.contexts){state.mode=saved.mode;state.hasPortfolio=saved.hasPortfolio!==false;for(const k of Object.keys(modes)){const c=saved.contexts[k];if(c&&typeof c.subject==='string'&&typeof c.thesis==='string'&&Number.isFinite(c.amount)&&c.amount>=1000&&c.amount<=1e9&&['balanced','conservative','aggressive'].includes(c.risk)&&['3–6  months','6–12  months','1–3  years','3  years or more'].includes(c.horizon)&&typeof c.holding==='string'&&Number.isInteger(c.version))state.contexts[k]=c}if(Array.isArray(saved.messages))state.messages=saved.messages.filter(m=>m&&typeof m.text==='string'&&typeof m.user==='boolean').slice(-100)}}catch{}
const current=()=>state.contexts[state.mode],money=n=>'¥'+n.toLocaleString('en-US');
function title(){const s=current();if(s.subject===modes[state.mode].subject)return modes[state.mode].title;return s.subject+' · '+modes[state.mode].name}
function report(s,m){const columns=(['stock','hedge','options'].includes(state.mode))?['Research topic / Plan','Current status','Category','Factors to consider']:['Underlying / Asset','Example weights','Portfolio role','Rationale (example)'];const scope=state.mode==='theme'||state.mode==='allocation';let rows=m.rows.map(row=>[...row]);if(s.risk==='conservative'&&scope){if(state.mode==='theme'){rows[0][1]='20%';rows[4][1]='25%'}else{rows[0][1]='35%';rows[1][1]='35%';rows[3][1]='20%'}}if(s.risk==='aggressive'&&scope){if(state.mode==='theme'){rows[0][1]='40%';rows[4][1]='5%'}else{rows[0][1]='70%';rows[1][1]='15%';rows[2][1]='5%'}}
return `<div class="report-meta"><span>${esc(m.name)} · ${esc(s.subject)}</span><span>${esc(s.horizon)}</span><span>Version ${String(s.version).padStart(2,'0')}</span></div><p class="report-lead">${esc(s.thesis)}</p><h3>Research background</h3><p>Reference amount ${money(s.amount)}; risk preference ${esc(s.risk)}; Current holdings: ${esc(s.holding||'Not provided')}.</p><h3>${scope?'Portfolio details and rationale':'Research details and plan notes'}</h3><div class="table-wrap"><table><thead><tr>${columns.map(c=>'<th>'+c+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')}</tbody></table></div><h3>Conditions to verify</h3>${m.questions.map(q=>'<p>· '+esc(q)+'</p>').join('')}<h3>Risks and invalidation conditions</h3>${m.watch.map(q=>'<p>'+esc(q)+'</p>').join('')}<h3>Data and scope</h3><p>This report demonstrates product interactions without live prices, financials, or backtests. Placeholder assets and weights are not recommendations for real assets. Chat edits affect example content only; model analysis is not connected.${state.mode==='hedge'?'Hedge ratio, contracts, cost, and effectiveness remain to be calculated.':''}</p>`}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2500)}
function mobile(v){document.body.classList.toggle('show-work',v==='work');document.querySelectorAll('[data-mobile]').forEach(e=>e.classList.toggle('selected',e.dataset.mobile===v))}
function openReport(){const dialog=$('#report-dialog');if(!dialog.open)dialog.showModal()}
function render(){syncShowcase(state.hasPortfolio);if(!state.hasPortfolio)return;const s=current(),m=modes[state.mode];$('#portfolio').classList.toggle('no-ring',state.mode==='options');$('#portfolio-name').textContent=s.subject+(state.mode==='hedge'?'Protection plan':state.mode==='stock'?'Related portfolio':'portfolio');$('#portfolio-caption').textContent=s.risk+' · '+s.horizon;$('#portfolio-note').textContent=state.mode==='stock'?'Not generated yet':state.mode==='hedge'?'Hedge ratio to be calculated':'Example portfolio';
if(state.mode==='options'){$('#portfolio-visual').innerHTML='<div class="generated-schematic">'+strategyScenes[1].svg+'<p>Illustrative expiry curve · Contracts and costs to be confirmed</p></div>'}else if(state.mode==='stock'||state.mode==='hedge'){$('#portfolio-visual').innerHTML=`<div class="minimal-state"><svg width="52" height="52" viewBox="0 0 52 52" fill="none" aria-hidden="true"><rect x="9" y="24" width="8" height="19" rx="2" stroke="currentColor" stroke-width="1.5"/><rect x="22" y="15" width="8" height="28" rx="2" stroke="currentColor" stroke-width="1.5"/><rect x="35" y="7" width="8" height="36" rx="2" stroke="currentColor" stroke-width="1.5"/></svg><h4>${state.mode==='stock'?'Start with an investment idea':'Keep the thesis, explore protection'}</h4><p>${state.mode==='stock'?'Continue chatting to turn security research into a portfolio.':'Recorded the holdings to protect. Protection methods, ratios, and costs are in the report.'}</p></div>`}else{const weights=state.mode==='theme'?(s.risk==='conservative'?[50,25,25]:s.risk==='aggressive'?[70,25,5]:[60,25,15]):(s.risk==='conservative'?[35,45,20]:s.risk==='aggressive'?[70,25,5]:[55,35,10]);const colors=['#365acb','#8aa6db','#b4cbc9'];let c=0;const gradient=weights.map((w,i)=>{const start=c;c+=w;return colors[i]+' '+start+'% '+c+'%'}).join(',');$('#portfolio-visual').innerHTML=`<div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Illustrative portfolio structure; see the report for weights"><div class="donut-center"><strong>${money(s.amount)}</strong><small>Planned investment amount</small></div></div><div class="legend">${m.blocks.map((b,i)=>'<span><i class="dot" style="background:'+colors[i]+'"></i>'+esc(b)+'</span>').join('')}</div>`}
$('#report-title').textContent=title()+' report';$('#report-content').innerHTML=report(s,m)}
function addMessage(text,user=false,remember=true){const e=document.createElement('div');e.className='msg';if(user){e.innerHTML='<div class="user"></div>';e.firstChild.textContent=text}else{e.innerHTML='<div class="who"><span class="aiicon">f</span>Folio</div><div class="bubble"></div>';e.lastChild.textContent=text}$('#messages').append(e);if(remember)state.messages.push({text,user});$('#messages').scrollTop=$('#messages').scrollHeight}
function initial(empty=false){$('#messages').innerHTML='<div class="intro"><h1>How would you like to invest?</h1><p>Discuss a market or security,<br>or explore options and risk hedging together.</p></div>';if(state.messages.length){for(const m of state.messages)addMessage(m.text,m.user,false)}else{addMessage('Start with an investment idea.\nChoose a strategy illustration on the right to explore it.',false,false)}const e=document.createElement('div');e.className='suggestions';e.innerHTML='<button class="chip" data-prompt="build a stock portfolio">Stock portfolio</button><button class="chip" data-prompt="build a call spread">Options portfolio</button><button class="chip" data-prompt="Design a hedge for existing holdings">Risk hedge</button>';$('#messages').append(e)}
function send(raw){const text=raw.trim();if(!text)return;addMessage(text,true);$('#prompt').value='';const s=current();if(/Report/.test(text)){if(!state.hasPortfolio){addMessage('No plan yet. Share an investment idea or choose a strategy example on the right.');return}openReport();addMessage('Report opened with portfolio details and rationale.');return}
if(!state.hasPortfolio&&!/options|spread|hedge|protection|pullback|lower |conservative|aggressive|Equities|NVIDIA|NVDA|Tesla|TSLA|Apple|AAPL|allocation|retirement|long term|portfolio|theme|market|bullish on |bearish|AI|amount|Capital|Budget|invest |horizon|Generate/i.test(text)){addMessage('Hello. What investment idea would you like to explore? Choose a stock, options, or hedge example on the right.');return}
state.hasPortfolio=true;
if(/options|spread/.test(text)){state.mode='options';current().version++;render();addMessage('Opened an illustrative call-spread structure.\nAdd the underlying, expiry, and budget; see the report for contract details and risks. These are not actual quotes.');return}
const amount=text.match(/(?:amount|Capital|Budget|invest )(?:change to |change to |adjust to |is |for |to |\s)*(\d+(?:\.\d+)?)\s*(k|k CNY|CNY)?/);const horizon=text.match(/(\d+)\s*(years?|months?)/);let updated=[];if(amount){const n=Number(amount[1])*(amount[2]?.startsWith('k')?1000:1);if(n>=1000&&n<=1e9){s.amount=n;updated.push('amount '+money(n))}else updated.push('Amount must be between 1,000 and 1 billion CNY')}if(horizon){const n=Number(horizon[1]);s.horizon=['year','years'].includes(horizon[2])?(n>=3?'3  years or more':'1–3  years'):(n<=6?'3–6  months':'6–12  months');updated.push('horizon '+s.horizon)}if(updated.length){s.version++;render();addMessage(updated.join(', ')+'.Portfolio and report synchronized.');return}
if(/hedge|protection|pullback/.test(text)){if(state.mode!=='hedge'){const h=state.contexts.hedge;h.subject=s.subject;h.amount=s.amount;h.holding=s.subject+'Related holdings (to be confirmed)';h.version++}state.mode='hedge';render();addMessage('A draft protection plan is ready for the current portfolio.\nTell me the protection horizon and acceptable cost; details are in the report.');return}
if(/lower |conservative|aggressive/.test(text)){if(['stock','hedge','options'].includes(state.mode)){addMessage('Provide the holdings to retain and capital size before adjusting risk. Weights remain to be calculated.');return}s.risk=/aggressive/.test(text)?'aggressive':'conservative';s.version++;render();addMessage('Adjusted to '+s.risk+'Example portfolio updated on the right.');return}
if(/Equities|NVIDIA|NVDA|Tesla|TSLA|Apple|AAPL/i.test(text)&&!/portfolio|build /.test(text)){state.mode='stock';const match=text.match(/NVIDIA|NVDA|Tesla|TSLA|Apple|AAPL/i);const names={'nvidia':'NVIDIA','nvda':'NVIDIA','tesla':'Tesla','tsla':'Tesla','apple':'Apple','aapl':'Apple'};current().subject=match?names[match[0].toLowerCase()]:'individual securities';current().thesis='research  '+current().subject+'  suitability for the portfolio.';render();addMessage('We can first discuss '+current().subject+' investment thesis. You can also ask to build a portfolio around it.\nSimulation demo without live market data.');return}
if(/allocation|retirement|long term/.test(text)){state.mode='allocation';render();addMessage('A draft long-term multi-asset portfolio is ready. Adjust the amount, horizon, and risk preferences through chat.');return}
if(/portfolio|theme|market|bullish on |AI/i.test(text)){if(state.mode==='stock'){state.contexts.theme.subject=current().subject+'theme';state.contexts.theme.thesis='around  '+current().subject+' discuss the portfolio.'}state.mode='theme';current().version++;render();addMessage('Portfolio draft updated. See the report for details and rationale.');return}
s.thesis=text.slice(0,300);s.version++;render();addMessage('Recorded in the report. You can continue with lower risk, change amount to  200k or horizon 3  years. This demo does not connect to live  AI.')}
document.addEventListener('click',e=>{const t=e.target.closest('[data-prompt],[data-mobile]');if(!t)return;if(t.dataset.prompt)send(t.dataset.prompt);else mobile(t.dataset.mobile)});
$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#prompt').value)};$('#prompt').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(e.target.value)}};
$('#open-report').onclick=openReport;$('#close-report').onclick=()=>$('#report-dialog').close();$('#export').onclick=()=>window.print();$('#save').onclick=()=>{try{localStorage.setItem('folio-simple-v3',JSON.stringify({...state,messages:state.messages.slice(-100)}));toast('Portfolio saved in this browser')}catch{toast('Unable to save; export through the report instead')}};
$('#new-chat').onclick=()=>{state.messages=[];state.mode='theme';state.contexts=Object.fromEntries(Object.keys(modes).map(k=>[k,fresh(k)]));state.hasPortfolio=false;render();initial(true);$('#prompt').focus()};initShowcase();render();initial();
